/* NAV */

#nav + br {
    display: none;
}
#nav {
    font-size: 1em;
    display: block !important;
    overflow: hidden;
    position: relative;
    background-color: #e5e5e5;
    padding: 2em 0;
    margin: 0 auto 2em;
    border-left: 2em solid #FFF;
    border-right: 2em solid #FFF;
    width: auto;
    max-width: 102em;
    border-bottom: none !important;
}
#nav::before {
    content: '';
    display: block;
    position: absolute;
    top: 0;
    left: 50%;
    bottom: 0;
    width: 5px;
    height: auto;
    transform: translateX(-50%);
    background-color: #FFF;
}
#nav td,
#nav tr,
#nav a,
#nav span,
#nav img,
#nav tbody,
#nav tr {
    display: block;
    overflow: hidden;
    padding: 0;
    margin: 0;
}
#nav {
    text-align: center;
    white-space: nowrap;
}
#nav td {
    width: auto;
    display: block;
    position: relative;
    z-index: 1;
    font-size: 1em;
    margin: 1em 0.5em 0;
}
#nav td:first-child {
    margin: 0 0.5em;
}

#nav td img {
    margin: 0 auto;
}
#nav span {
    display: block;
}
#nav span {
    display: block;
    position: relative;
}
