    overflow: hidden;
}
form[name="details"] td:first-child,
form[name="bankdetails"] td:first-child {
    font-family: 'Montserrat', Helvetica, Arial, sans-serif;
    font-weight: 700;
}
.star {
    color: #C00;
}
fieldset {
    margin: 0 auto;
    border-top: 1px solid #e5e5e5;
    border-left: 1px solid #e5e5e5;
    border-right: 1px solid #e5e5e5;
    border-bottom: 5px solid #e5e5e5;
    max-width: 98em;
    box-sizing: border-box;
    margin: 0 auto 1em;
    padding: 2.5em 0.9em 0.9em;
    position: relative;
}
fieldset legend {
    display: block;
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    font-size: 1.4em;
    line-height: 1.429em;
    margin: 0;
    padding: 0;
    font-family: 'Montserrat', Helvetica, Arial, sans-serif;
    font-weight: 700;
    border: none;
    outline: none;
    color: #666;
    width: 100%;
    box-sizing: border-box;
    padding: 0.714em;
    background-color: #e5e5e5;
    white-space: nowrap;
    cursor: pointer;
    cursor: hand;
}
i,
fieldset legend i {
    display: none !important;
}
input {
    font-family: 'Open Sans', Helvetica, Arial, sans-serif;
    font-weight: 400;
    font-size: 14px;
}
td input.text,
td input[type="text"],
td input[type="password"],
td input[type="email"],
td input[type="url"],
td input[type="number"],
td input[type="tel"] {
    font-size: 1em;
}
input.text,
input[type="text"],
input[type="password"],
input[type="email"],
input[type="url"],
input[type="number"],
input[type="tel"] {
    border-radius: 0;
    width: 100%;
    display: block;
    line-height: 40px;
    height: 40px;
    padding: 0 5px;
    border: 1px solid #CCCCCC;
    transition: all 0.5s ease-out;
    font-size: 1.4em;
    box-sizing: border-box;
    max-width: 600px;
}
#ddaccno {
    width: 100%;
}
input[type="tel"] {
    max-width: 300px;
}
#ddsort1,
#ddsort2,
#ddsort3 {
    display: inline-block;
}
select[name="dddobd"],
select[name="dddobm"],
select[name="dddoby"] {
    display: inline-block;
    width: 190px;
    margin-right: 10px;
}
select[name="dddoby"] {
    width: 194px;
}
textarea {
    width: 100%;
    display: block;
    padding: 5px 5px;
    border: 1px solid #CCCCCC;
    transition: all 0.5s ease-out;
    font-size: 1.4em;
    line-height: 1.286em;
    font-family: 'Open Sans', Helvetica, Arial, sans-serif;
    font-weight: 400;
    box-sizing: border-box;
    height: 200px;
    max-width: 600px;
}
input.text:focus,
input[type="text"]:focus,
input[type="password"]:focus,
input[type="email"]:focus,
input[type="url"]:focus,
input[type="number"]:focus,
textarea:focus {
    border: 1px solid #333333;
    box-shadow: none;
    background: none;
}
select {
    width: 100%;
    outline: none;
    border: none;
    height: 40px;
    line-height: 20px;
    padding: 4px;
    border: 1px solid #CCC;
    transition: all 0.5s ease-out;
    font-size: 14px;
    font-family: 'Open Sans', Helvetica, Arial, sans-serif;
    font-weight: 400;
    vertical-align: middle;
    border-radius: 0;
    max-width: 600px;
}
select:focus {
    border: 1px solid #333333;
    box-shadow: none;
    background: none;
}
hr {
    display: block;
    width: 100%;
    height: 5px;
    color: #E5E5E5;
    background-color: #E5E5E5;
    margin: 4em 0;
    clear: both;
    outline: none;
    border: none;
}

/* TABLE */

table:empty {
    display: none;
}
table {
    max-width: 98em;
    margin: 2em auto;
    border-spacing: 0;
    border-collapse: collapse;
}
table td {
    font-size: 1.4em;
    line-height: 1.714em;
    padding-bottom: 0.714em;
}
table td p {
    font-size: 1em;
}
table td[height="10"],
table td[height="5"] {
    display: none;
}
form[name="plan"] {
    padding: 0;
    margin: 0 auto;
    max-width: 98em;
}
form[name="confirmation"] {
    max-width: 98em;
    margin: 0 auto;
}
form[name="confirmation"] table fieldset {
    font-size: 1em;
    padding: 0.714em;
    border: 5px solid #e5e5e5;
}
form[name="confirmation"] td:first-child {
    font-family: 'Montserrat', Helvetica, Arial, sans-serif;
    font-weight: 700;
}
form[name="confirmation"] table,
form[name="confirmation"] td,
form[name="confirmation"] tr {
    padding: 0;
    display: block;
    overflow: hidden;
    width: 100%;
}
form[name="confirmation"] tr {
    margin-bottom: 0.5em;
}
form[name="confirmation"] table td:empty {
    display: none;
}
form[name="confirmation"] table td > span {
    font-family: 'Montserrat', Helvetica, Arial, sans-serif !important;
    font-weight: 700 !important;
    font-size: 1em !important;
}
form[name="confirmation"] center {
    font-family: 'Montserrat', Helvetica, Arial, sans-serif;
    font-weight: 700;
    font-size: 1.4em;
    line-height: 1.714em;
}
@media all and (min-width: 640px) {
    form[name="confirmation"] td {
        width: 50%;
        float: left;
    }
    form[name="confirmation"] td:first-child {
        padding-right: 0.714em;
    }
    form[name="confirmation"] td:last-child {
        padding-left: 0.714em;
    }
}

/* BUTTONS */

.planselector--button {
    padding: 0;
    margin: 0;
    vertical-align: top;
}
.planselector--button a {
    display: block;
    padding: 0;
    margin: 0;
    position: relative;
}

/* MISC */

h2 {
    font-size: 2.4em;
    line-height: 1.2em;
    margin: 0 0 0.417em 0;
}
h2 span {
    font-size: 1em;
    display: inline;
}
#breakdown,
#breakdown + div[align="center"],
.footernav {
    max-width: 98em;
    margin: 0 auto;
}
.footernav > input {
    float: left;
    margin-left: 10px;
    filter: gray;
    filter: grayscale(100%);
}
#content .footernav {
    background-color: #e5e5e5;
    padding: 1em;
}
#content .next {
    float: right;
}

/* FOOTER */

.bottombar-image {
    display: none !important;
}
#footer {
    display: none;
}
.msgrbroundbox .msgrbbot {
    background: none;
    height: auto;
}
.msgrbroundbox .msgrbbot::before {
    content: 'South Tyneside includes the towns of South Shields, Hebburn and Jarrow and the villages of Boldon, Cleadon and Whitburn.';
    display: block;
    overflow: hidden;
    font-size: 1.4em;
    line-height: 1.714em;
    padding: 1.429em;
    text-align: center;
    border-top: 1px solid #e5e5e5;
    margin-top: 2.857em;
}
.msgrbroundbox .msgrbbot::after {
    display: block;
    overflow: hidden;
    content: 'South Tyneside Council';
    font-size: 1.4em;
    line-height: 1.714em;
    padding: 1.429em;
    text-align: center;
    border-top: 1px solid #ccc;
    background-color: #e5e5e5;
    background-image: url('https://www.southtyneside.gov.uk/themes/southtyneside/images/bg-halftone.png');
}
#cent > br {
    display: none;
}

form  > p.errortext,
span.errortext {
    display: block;
    overflow: hidden;
    margin: 0.5em auto;
    color: #FFF;
    background-color: #C00;
    padding: 0.5em;
    font-size: 20px;
    line-height: 1em;
    font-family: 'Montserrat', Helvetica, Arial, sans-serif;
    background-image: url('https://www.southtyneside.gov.uk/themes/southtyneside/images/bg-halftone.png');
}

legend .fa {
    display: none !important;
}

legend span.errortext {
    font-size: 10px;
