    top: 10px;
    right: 0;
}

td .fa,
form  > p.errortext .fa {
    display: none !important;
}

td span.errortext  {
    max-width: 600px;
}

td[colspan="3"] span.errortext {
    font-size: 1em;
    max-width: none;
    margin-top: 0;
}

span.errortext::before,
form  > p.errortext::before {
    content: '\f057';
    font-family: 'FontAwesome';
    margin-right: 0.25em;
}

table td span.errortext {
    font-size: 20px;
    margin-left: 0;
    margin-right: 0;
    max-width: none;
}

